import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import {
  StorageProviderError,
  type PutObjectInput,
  type StorageProvider,
} from './storage-provider';

// Desktop edition (DEC-117, DEC-120): objects as files under the user's data
// folder, behind the same interface as S3. Keys are generated by CASEFlow,
// but are still confined to the root: a key can never reach outside it.
export class FilesystemStorageProvider implements StorageProvider {
  readonly id = 'filesystem';
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  async putObject(input: PutObjectInput): Promise<void> {
    const path = this.pathFor(input.key);
    try {
      await mkdir(dirname(path), { recursive: true });
      // Written aside and renamed, so a reader never sees half a file.
      const partial = `${path}.partial`;
      await writeFile(partial, input.body);
      await rename(partial, path);
    } catch (cause) {
      throw new StorageProviderError('STORAGE_PROVIDER_ERROR', 'No se pudo guardar el archivo.', {
        cause,
      });
    }
  }

  async getObject(key: string): Promise<Buffer> {
    try {
      return await readFile(this.pathFor(key));
    } catch (cause) {
      if ((cause as NodeJS.ErrnoException).code === 'ENOENT')
        throw new StorageProviderError('STORAGE_OBJECT_NOT_FOUND', 'El objeto no existe.', {
          cause,
        });
      throw new StorageProviderError('STORAGE_PROVIDER_ERROR', 'No se pudo leer el archivo.', {
        cause,
      });
    }
  }

  private pathFor(key: string): string {
    const path = resolve(this.root, key);
    // Keys use '/' on every platform; a backslash is never a CASEFlow key.
    if (!key || key.includes('\\') || !path.startsWith(this.root + sep))
      throw new StorageProviderError('STORAGE_PROVIDER_ERROR', 'La clave del objeto no es válida.');
    return path;
  }
}
